import { cookies } from 'next/headers'
import { toggleNotifications } from './actions'

export default async function Home() {
  const cookieStore = await cookies()
  const notificationPreference = cookieStore.get('notifications')?.value || 'off'

  return (
    <main>
      <h1>Settings</h1>
      <p>Notification Preference: <strong>{notificationPreference}</strong></p>

      <form action={toggleNotifications}>
        <button type="submit">
          Toggle Notifications ({notificationPreference === 'on' ? 'Turn Off' : 'Turn On'})
        </button>
      </form>
    </main>
  );
}

